// The SCADA symbol manifest: what every symbol of the library is, without its drawing. The templates, select validation, the
// search and the server read it; the registry (`scada-logic.ts`) draws the base symbols itself and gets each pack file's drawings
// at run time from the IoT module `dashboard_scada`. Regenerate after a change to a symbol's key, name, family, flags, box or rows:
//   node_modules/.bin/tsx modules/dashboard_scada/scripts/scada-manifest.mts

import type { ScadaFamily, ScadaTrack } from './scada-logic';

/**
 * A symbol's metadata. `pack` is the pack file that draws it (`scada-pack-<id>.ts` in dashboard_scada; `base` = the registry's
 * own); `w` x `h` is its box at rest, not turned, one cell long (what the placeholder takes while the pack has not arrived).
 */
export interface ScadaManifestEntry {
  family: ScadaFamily;
  label: string;
  pack: string;
  w: number;
  h: number;
  scaled?: true;
  valueUnder?: true;
  runs?: true;
  rows?: true;
  /** A tracking symbol's default role and point in its box at rest (TP-2). */
  track?: ScadaTrack;
}

